                    performance: { overallScore: 0, score: 0, grade: 'F', tier: 'needs_improvement' },
                    performanceTier: 'needs_improvement'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    banrepForecast: 'cut50',
                    curveStrategy: 'bullet',
                    durationTarget: 4.82,
                    creditStance: 'neutral',
                    petrosinuDecision: 'pass',
                    valmoranAction: 'hold',
                    tesDecision: 'maintain',
                    stressTestResult: 0,
                    targetDuration: 5.0,
                    targetTes: 65,
                    targetCorp: 18,
                    incomeAttribution: 0,
                    durationAttribution: 0,
                    curveAttribution: 0,
                    creditAttribution: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            var t = function(k) { try { return window.mySimulation.t(k); } catch (e) { return k; } };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = t(round.briefingKey);
            }

            var ds = null;
            try { ds = window.mySimulation.state.domainState; } catch(e) {}
            if (!ds) return;

            var logEl = document.getElementById('eventLogContent');
            if (logEl && ds.eventLog) {
                logEl.innerHTML = ds.eventLog.map(function(ev) {
                    return (ev && typeof ev === 'object') ? 'R' + ev.r + ': ' + t(ev.k) : ev;
                }).join('<br>');
            }

            var varCheckEl = document.getElementById('varCheckDisplay');
            if (varCheckEl) {
                varCheckEl.textContent = ds.var95Pct.toFixed(2) + '%';
                if (ds.var95Pct > 1.40) {
                    varCheckEl.style.color = '#dc3545';
                } else {
                    varCheckEl.style.color = '#28a745';
                }
            }

            var cpiEl = document.getElementById('cpiDisplay');
            if (cpiEl) cpiEl.textContent = ds.cpi.toFixed(1) + '%';
            var gdpEl = document.getElementById('gdpDisplay');
            if (gdpEl) gdpEl.textContent = ds.gdpGrowth.toFixed(1) + '%';
            var fiscalEl = document.getElementById('fiscalDisplay');
            if (fiscalEl) fiscalEl.textContent = ds.fiscalDeficit.toFixed(1) + '%';
            var cdsEl = document.getElementById('cdsDisplay');
            if (cdsEl) cdsEl.textContent = Math.round(ds.sovereignCDS) + ' bps';
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state.currentPeriod || 1);

            if (round === 1) {
                var bf = document.getElementById('banrepForecastSelect');
                if (bf) decisions.banrepForecast = bf.value;
                var cs = document.getElementById('curveStrategySelect');
                if (cs) decisions.curveStrategy = cs.value;
                var dt = document.getElementById('durationTargetInput');
                if (dt) decisions.durationTarget = parseFloat(dt.value);
                if (!decisions.durationTarget || decisions.durationTarget < 3.5 || decisions.durationTarget > 7.5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('duration_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 2) {
                var cst = document.getElementById('creditStanceSelect');
                if (cst) decisions.creditStance = cst.value;
                var eco = document.getElementById('petrosinuSelect');
                if (eco) decisions.petrosinuDecision = eco.value;
            } else if (round === 3) {
                var ica = document.getElementById('valmoranSelect');
                if (ica) decisions.valmoranAction = ica.value;
                var td = document.getElementById('tesDecisionSelect');
                if (td) decisions.tesDecision = td.value;
                var st = document.getElementById('stressTestInput');
                if (st) decisions.stressTestResult = parseFloat(st.value);
                if (!decisions.stressTestResult || decisions.stressTestResult <= 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('stress_test_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 4) {
                var tdi = document.getElementById('targetDurationInput');
                if (tdi) decisions.targetDuration = parseFloat(tdi.value);
                var tti = document.getElementById('targetTesInput');
                if (tti) decisions.targetTes = parseFloat(tti.value);
                var tci = document.getElementById('targetCorpInput');
                if (tci) decisions.targetCorp = parseFloat(tci.value);
                var ia = document.getElementById('incomeAttrInput');
                if (ia) decisions.incomeAttribution = parseFloat(ia.value) || 0;
                var da = document.getElementById('durationAttrInput');
                if (da) decisions.durationAttribution = parseFloat(da.value) || 0;
                var ca = document.getElementById('curveAttrInput');
                if (ca) decisions.curveAttribution = parseFloat(ca.value) || 0;
                var cra = document.getElementById('creditAttrInput');
                if (cra) decisions.creditAttribution = parseFloat(cra.value) || 0;
                if (decisions.targetTes < 55 || decisions.targetTes > 85) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('tes_alloc_warning'), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var portReturnBps = 0;
            var benchReturnBps = 0;
            var incomeComponent = 0;
            var durationComponent = 0;
            var curveComponent = 0;
            var creditComponent = 0;
            var roundEvents = [];

            var randomEvts = this.RANDOM_EVENTS[round - 1] || [];
            var firedThisRound = [];
            // Deterministic per-(session,round) event rolls: reproducible + undo-idempotent.
            var er = this._prng((this._baseSeed(state) ^ Math.imul(round, 0x9E3779B1)) >>> 0);
            for (var e = 0; e < randomEvts.length; e++) {
                if (er() < randomEvts[e].prob) {
                    firedThisRound.push(randomEvts[e]);
                    roundEvents.push({ r: round, k: randomEvts[e].msgKey });
                }
            }

            var hasBullSteepener = firedThisRound.some(function(ev) { return ev.effect === 'bullSteepener'; });
            var hasCdsSovShock = firedThisRound.some(function(ev) { return ev.effect === 'cdsSovShock'; });
            var hasUsdStrength = firedThisRound.some(function(ev) { return ev.effect === 'usdStrength'; });
            var hasEarlyRecovery = firedThisRound.some(function(ev) { return ev.effect === 'earlyRecovery'; });
            var hasSfcQuery = firedThisRound.some(function(ev) { return ev.effect === 'sfcQuery'; });
            var hasOilDrop = firedThisRound.some(function(ev) { return ev.effect === 'oilDrop'; });

            var quarterlyIncome = 55;
            incomeComponent = quarterlyIncome;
            benchReturnBps += quarterlyIncome;

            if (round === 1) {
                var actualBanrepCut = 50;
                ds.banrepRate = 8.75;

                var forecastScore = 0;
                if (d.banrepForecast === 'cut50') forecastScore = 30;
                else if (d.banrepForecast === 'cut25') forecastScore = 15;
                else if (d.banrepForecast === 'hold') forecastScore = 5;
                else forecastScore = 0;
                ds.durationScore += forecastScore;

                var benchYieldChangeBps = -30;
                var effectiveYieldChangeBps = -30;
                if (d.curveStrategy === 'barbell') {
                    effectiveYieldChangeBps = -35;
                    curveComponent = 5 * d.durationTarget / 5.0;
                } else if (d.curveStrategy === 'bullet') {
                    effectiveYieldChangeBps = -30;
                    curveComponent = 0;
                } else {
                    effectiveYieldChangeBps = -28;
                    curveComponent = -2 * d.durationTarget / 5.0;
                }

                if (hasBullSteepener) {
                    effectiveYieldChangeBps -= 12;
                    benchYieldChangeBps -= 8;
                    if (d.curveStrategy === 'barbell') {
                        curveComponent += 8;
                    }
                }

                durationComponent = Math.round(d.durationTarget * Math.abs(effectiveYieldChangeBps) / 100 * 100);
                var benchDurationEffect = Math.round(5.0 * Math.abs(benchYieldChangeBps) / 100 * 100);

                portReturnBps = incomeComponent + durationComponent + Math.round(curveComponent);
                benchReturnBps += benchDurationEffect;

                ds.duration = d.durationTarget;
                ds.cpi = 5.2;
                ds.gdpGrowth = 1.6;

                ds.durationScore += Math.round(Math.max(0, 40 - Math.abs(d.durationTarget - 6.0) * 15));

            } else if (round === 2) {
                var igSpreadChange = -15;
                var subIgSpreadChange = 25;

                if (d.creditStance === 'defensive') {
                    creditComponent = Math.round(igSpreadChange * -0.12 * ds.duration);
                    ds.corpIGAllocation = 15;
                    ds.corpSubIGAllocation = 3;
                    ds.creditCorrect += 1;
                    ds.creditDecisions += 2;
                } else if (d.creditStance === 'neutral') {
                    creditComponent = Math.round((igSpreadChange * -0.18 + subIgSpreadChange * -0.05) * ds.duration);
                    ds.creditCorrect += 1;
                    ds.creditDecisions += 2;
                } else {
                    creditComponent = Math.round((igSpreadChange * -0.22 + subIgSpreadChange * -0.10) * ds.duration);
                    ds.corpIGAllocation = 22;
                    ds.corpSubIGAllocation = 8;
                    ds.creditDecisions += 2;
                }

                var ecoEffect = 0;
                if (d.petrosinuDecision === 'buy5') {
                    ecoEffect = 12;
                    ds.usdAllocation = Math.min(15, ds.usdAllocation + 5);
                    ds.creditCorrect += 1;
                } else if (d.petrosinuDecision === 'buy10') {
                    ecoEffect = 22;
                    ds.usdAllocation = Math.min(15, ds.usdAllocation + 10);
                    ds.creditCorrect += 1;
                } else if (d.petrosinuDecision === 'cdsShort') {
                    ecoEffect = -8;
                }
                ds.creditDecisions += 1;
                creditComponent += ecoEffect;

                if (hasCdsSovShock) {
                    ds.sovereignCDS += 30;
                    var sovShockBps = -Math.round(30 * ds.duration * 0.15);
                    durationComponent += sovShockBps;
                    portReturnBps += sovShockBps;
                    benchReturnBps += Math.round(sovShockBps * 0.9);
                }

                if (hasUsdStrength) {
                    var usdBonusBps = Math.round(ds.usdAllocation * 2.5);
                    creditComponent += usdBonusBps;
                }

                var benchYieldMove2 = -10;
                durationComponent += Math.round(ds.duration * Math.abs(benchYieldMove2) / 100 * 100);
                benchReturnBps += Math.round(5.0 * Math.abs(benchYieldMove2) / 100 * 100);

                portReturnBps = incomeComponent + durationComponent + creditComponent;

                ds.var95Pct = 0.85 + ds.duration * 0.12 + (ds.corpSubIGAllocation * 0.02);
                if (ds.var95Pct > 1.40) ds.varCompliant = false;

                ds.banrepRate = 8.75;
                ds.cpi = 4.8;
                ds.gdpGrowth = 1.8;
                ds.fiscalDeficit = -3.9;

            } else if (round === 3) {
                var valmoranLossBps = 0;
                var induWeight = 0.04;

                if (d.valmoranAction === 'hold') {
                    if (hasEarlyRecovery) {
                        valmoranLossBps = -Math.round(induWeight * 10000 * 0.15);
                        ds.creditCorrect += 1;
                    } else {
                        valmoranLossBps = -Math.round(induWeight * 10000 * 0.55);
                    }
                } else if (d.valmoranAction === 'sellMarket') {
                    valmoranLossBps = -Math.round(induWeight * 10000 * 0.35);
                    ds.creditCorrect += 1;
                } else if (d.valmoranAction === 'sellDistressed') {
                    valmoranLossBps = -Math.round(induWeight * 10000 * 0.55);
                } else if (d.valmoranAction === 'cdsHedge') {
                    valmoranLossBps = -Math.round(induWeight * 10000 * 0.10);
                    ds.creditCorrect += 1;
                }
                ds.creditDecisions += 1;

                var sovSpreadWidenBps = 20;
                ds.sovereignCDS += 45;
                var sovLoss = -Math.round(ds.duration * sovSpreadWidenBps / 100 * 100);

                if (d.tesDecision === 'reduce') {
                    sovLoss = Math.round(sovLoss * 0.65);
                    ds.tesAllocation = 58;
                } else {
                    ds.tesAllocation = 65;
                }

                durationComponent = sovLoss;
                creditComponent = valmoranLossBps;

                var correctStressTest = Math.round(ds.duration * 5.0 * ds.portfolioValue) / 100;
                var stressTestError = Math.abs(d.stressTestResult - correctStressTest);
                var stressTestScore = Math.max(0, 100 - stressTestError * 2);

                benchReturnBps += Math.round(-5.0 * sovSpreadWidenBps / 100 * 100);
                benchReturnBps += Math.round(-0.04 * 10000 * 0.30);

                portReturnBps = incomeComponent + durationComponent + creditComponent;

                if (hasSfcQuery) {
                    ds.varCompliant = ds.var95Pct <= 1.40;
                }

                ds.var95Pct = 0.90 + ds.duration * 0.14 + (ds.corpSubIGAllocation * 0.025);
                ds.cpi = 4.5;
                ds.gdpGrowth = 1.5;
                ds.fiscalDeficit = -4.5;

            } else if (round === 4) {
                var easeSignalBps = -25;
                durationComponent = Math.round(ds.duration * Math.abs(easeSignalBps) / 100 * 100);
                benchReturnBps += Math.round(5.0 * Math.abs(easeSignalBps) / 100 * 100);

                var recoverySpreadTighten = 10;
                creditComponent = Math.round(recoverySpreadTighten * ds.corpIGAllocation / 100 * ds.duration);

                if (hasOilDrop) {
                    var ecoLoss = 0;
                    if (ds.usdAllocation > 12) {
                        ecoLoss = -Math.round((ds.usdAllocation - 12) * 4);
                    }
                    creditComponent += ecoLoss;
                }

                portReturnBps = incomeComponent + durationComponent + creditComponent + Math.round(curveComponent);

                ds.duration = d.targetDuration;
                ds.tesAllocation = d.targetTes;
                ds.corpIGAllocation = Math.min(d.targetCorp, 20);
                ds.usdAllocation = Math.max(0, 100 - d.targetTes - d.targetCorp - ds.corpSubIGAllocation);

                ds.banrepRate = Math.max(7.50, ds.banrepRate - 0.50);
                ds.sovereignCDS = Math.max(150, ds.sovereignCDS - 15);
                ds.cpi = 4.0;
                ds.gdpGrowth = 2.0;
            }

            ds.actualIncomeAttr += incomeComponent;
            ds.actualDurationAttr += durationComponent;
            ds.actualCurveAttr += Math.round(curveComponent);
            ds.actualCreditAttr += creditComponent;

            var portValueChange = ds.portfolioValue * portReturnBps / 10000;
            var benchValueChange = ds.benchmarkValue * benchReturnBps / 10000;
            ds.portfolioValue += portValueChange;
            ds.benchmarkValue += benchValueChange;
            ds.cumulativeReturnBps += portReturnBps;
            ds.benchmarkReturnBps += benchReturnBps;
            ds.excessReturnBps = ds.cumulativeReturnBps - ds.benchmarkReturnBps;

            ds.portfolioHistory.push(Math.round(ds.portfolioValue * 10) / 10);
            ds.benchmarkHistory.push(Math.round(ds.benchmarkValue * 10) / 10);
            ds.durationHistory.push(ds.duration);
            ds.excessHistory.push(ds.excessReturnBps);

            for (var re = 0; re < roundEvents.length; re++) {
                ds.eventLog.push(roundEvents[re]);
            }
            ds.firedEvents = ds.firedEvents.concat(firedThisRound.map(function(ev) { return ev.effect; }));

            var attributionError = 0;
            if (round === 4) {
                attributionError = Math.abs(d.incomeAttribution - ds.actualIncomeAttr)
                    + Math.abs(d.durationAttribution - ds.actualDurationAttr)
                    + Math.abs(d.curveAttribution - ds.actualCurveAttr)
                    + Math.abs(d.creditAttribution - ds.actualCreditAttr);
                attributionError = Math.round(attributionError / 4);
            }

            // --- Grading & Reporting Contract (C1): persist the 0-100 composite every period ---
            var overallScore = this._composite(ds, attributionError);
            var tier = this._tier(overallScore);
            ds.performanceTier = tier;
            ds.performance = { overallScore: overallScore, score: overallScore, grade: this._grade(overallScore), tier: tier };

            // Advance the briefing to the next round from the single source of truth (state is
            // already at N+1 here); prior code added +1 to the incremented value, skipping a round.
            var self = this;
            if (round < 4) {
                setTimeout(function() { self._updateBriefing(state); }, 500);
            }

            return {
                period: round,
                portfolioReturnBps: portReturnBps,
                benchmarkReturnBps: benchReturnBps,
                excessReturnBps: portReturnBps - benchReturnBps,
                incomeEffect: incomeComponent,
                durationEffect: durationComponent,
                curveEffect: Math.round(curveComponent),
                creditEffect: creditComponent,
                portfolioValue: Math.round(ds.portfolioValue * 10) / 10,
                duration: ds.duration,
                var95: Math.round(ds.var95Pct * 100) / 100,
                events: roundEvents.length,
                attributionError: attributionError,
                overallScore: overallScore,
                score: overallScore,
                performance: ds.performance
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('portfolioDisplay', 'domainState.portfolioValue',
                function(v) { return 'COP ' + v.toFixed(1) + 'B'; });
            uiManager.bind('durationDisplay', 'domainState.duration',
                function(v) { return v.toFixed(2); });
            uiManager.bind('varDisplay', 'domainState.var95Pct',
                function(v) { return v.toFixed(2) + '%'; });
            uiManager.bind('excessDisplay', 'domainState.excessReturnBps',
                function(v) { return (v >= 0 ? '+' : '') + Math.round(v) + ' bps'; });
            uiManager.bind('banrepDisplay', 'domainState.banrepRate',
                function(v) { return v.toFixed(2) + '%'; });
            uiManager.bind('tesAllocDisplay', 'domainState.tesAllocation',
                function(v) { return Math.round(v) + '%'; });
            var self = this;
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function' && !this._langHooked) {
                this._langHooked = true;
                f.eventBus.on('language:changed', function() {
                    if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state);
                });
            }
        }

