        getChartData(state) {
            var labels = state.domainState.portfolioHistory.map(function(_, i) { return 'R' + (i + 1); });
            var exColors = state.domainState.excessHistory.map(function(v) {
                return v >= 0 ? 'rgba(39,174,96,0.7)' : 'rgba(220,53,69,0.7)';
            });
            return {
                performanceChart: {
