        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k) { try { return window.mySimulation.t(k); } catch (e) { return k; } };
            var ds = window.mySimulation.state.domainState;
            var totalExcess = ds.excessReturnBps;
            var dms = Math.min(100, ds.durationScore);
            var caa = ds.creditDecisions > 0 ? Math.round(ds.creditCorrect / ds.creditDecisions * 100) : 0;
            var vcr = ds.varCompliant ? 100 : 50;

            var lastRound = history[history.length - 1];
            var attrErr = lastRound && lastRound.results ? (lastRound.results.attributionError || 0) : 0;
            var aa = Math.max(0, 100 - attrErr * 2);

            var composite = this._composite(ds, attrErr);   // clamped 0-100, single source
            var tier = this._tier(composite);

            var insightKeys = [];
            if (totalExcess > 80) insightKeys.push('ins_strong_excess');
            else if (totalExcess > 0) insightKeys.push('ins_pos_excess');
            else insightKeys.push('ins_underperf');
            insightKeys.push(dms >= 70 ? 'ins_dur_good' : 'ins_dur_weak');
            insightKeys.push(caa >= 65 ? 'ins_credit_good' : 'ins_credit_weak');
            if (!ds.varCompliant) insightKeys.push('ins_var_breach');
            var insights = insightKeys.map(function(k) { return t(k); });

            return {
                overallScore: composite,
                score: composite,
                grade: this._grade(composite),
                compositeScore: composite,
                totalExcessReturn: totalExcess,
                durationManagementScore: dms,
                creditAccuracy: caa,
                varCompliance: vcr,
                attributionAccuracy: aa,
                performance: tier,                 // stable slug for analytics equality
                performanceTier: tier,
                performanceLabel: this._tierLabel(tier),
                officialAttribution: {
                    income: ds.actualIncomeAttr,
                    duration: ds.actualDurationAttr,
                    curve: ds.actualCurveAttr,
                    credit: ds.actualCreditAttr
                },
                insights: insights,
                insightKeys: insightKeys
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k) { try { return window.mySimulation.t(k); } catch (e) { return k; } };
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var grade = summary.grade || this._grade(score);
            var label = summary.performanceLabel || this._tierLabel(summary.performanceTier || summary.performance || 'needs_improvement');
            var excess = summary.totalExcessReturn || 0;
            var insights = summary.insights || [];
            var insightsHtml = '';
            if (insights.length) {
                insightsHtml = '<div class="bonos-sim-cm-insights"><div class="bonos-sim-cm-insights-title">' +
                    t('cm_insights_title') + '</div><ul>';
                insights.forEach(function(s) { insightsHtml += '<li>' + s + '</li>'; });
                insightsHtml += '</ul></div>';
            }
            return '' +
                '<div class="bonos-sim-cm">' +
                    '<div class="bonos-sim-cm-title">' + t('cm_title') + '</div>' +
                    '<div class="bonos-sim-cm-scorebox">' +
                        '<span class="bonos-sim-cm-score">' + score + '</span>' +
                        '<span class="bonos-sim-cm-score-max">/100</span>' +
                        '<span class="bonos-sim-cm-grade">' + t('cm_grade') + ' ' + grade + '</span>' +
                    '</div>' +
                    '<div class="bonos-sim-cm-verdict">' + t('cm_verdict') + ': <strong>' + label + '</strong></div>' +
                    '<div class="bonos-sim-cm-kpis">' +
                        '<div class="bonos-sim-cm-kpi"><span>' + (excess >= 0 ? '+' : '') + Math.round(excess) + '</span><label>' + t('cm_excess') + '</label></div>' +
                        '<div class="bonos-sim-cm-kpi"><span>' + (summary.durationManagementScore || 0) + '</span><label>' + t('cm_duration') + '</label></div>' +
                        '<div class="bonos-sim-cm-kpi"><span>' + (summary.creditAccuracy || 0) + '%</span><label>' + t('cm_credit') + '</label></div>' +
