        }

        getHint(state, results) {
            if (!results) return null;
            var round = results.period;
            if (round === 1 && results.excessReturnBps < 0) {
                return window.mySimulation.t('hint_r1_underperform');
            }
            if (round === 2 && state.domainState.var95Pct > 1.30) {
                return window.mySimulation.t('hint_var_warning');
            }
            if (round === 3 && results.creditEffect < -100) {
                return window.mySimulation.t('hint_r3_credit_loss');
            }
            if (round === 4 && results.excessReturnBps > 0) {
                return window.mySimulation.t('hint_r4_positive');
            }
            return null;
        }

