            return [
                { key: 'results.portfolioReturnBps', label: 'Port Return (bps)', i18nKey: 'col_port_return', formatter: function(v) { return (v >= 0 ? '+' : '') + Math.round(v); } },
                { key: 'results.benchmarkReturnBps', label: 'Bench Return (bps)', i18nKey: 'col_bench_return', formatter: function(v) { return (v >= 0 ? '+' : '') + Math.round(v); } },
                { key: 'results.excessReturnBps', label: 'Excess (bps)', i18nKey: 'col_excess', formatter: function(v) { return (v >= 0 ? '+' : '') + Math.round(v); } },
                { key: 'results.incomeEffect', label: 'Income', i18nKey: 'col_income', formatter: function(v) { return Math.round(v) + ' bps'; } },
