                { key: 'results.creditEffect', label: 'Credit', i18nKey: 'col_credit_eff', formatter: function(v) { return Math.round(v) + ' bps'; } },
                { key: 'results.portfolioValue', label: 'Port Value (COP B)', i18nKey: 'col_port_value', formatter: function(v) { return v.toFixed(1); } }
